#!/usr/bin/env bash
# Wraps monitoring/rules/audio-jobs.rules.yml (plain Prometheus rule file,
# tested with promtool) into the PrometheusRule object the operator loads.
# With --check, fails if the committed object is out of date instead.
set -euo pipefail
cd "$(dirname "$0")/.."
src=monitoring/rules/audio-jobs.rules.yml
dst=monitoring/rules/prometheusrule.yaml

render() {
  cat <<'EOF'
# Generated by scripts/render-rules.sh from audio-jobs.rules.yml. Do not edit.
apiVersion: monitoring.coreos.com/v1
kind: PrometheusRule
metadata:
  name: audio-jobs
spec:
EOF
  grep -v '^#' "$src" | sed '/./s/^/  /'
}

if [[ ${1:-} == --check ]]; then
  if ! diff -u "$dst" <(render); then
    echo "$dst is out of date; run scripts/render-rules.sh" >&2
    exit 1
  fi
  echo "$dst is up to date"
else
  render >"$dst"
  echo "wrote $dst"
fi
